    if (post){ const r=meOLS(Xc.map(x=>sel.map(j=>x[j])), yc); e1=r.resid; coef=new Array(p).fill(0); sel.forEach((j,q)=>coef[j]=r.beta[q]); } else { coef=b; e1=yc.map((v,i)=>v-meDot(b,Xc[i])); }
